or_span\": \"Document data definitions, provenance, and permitted uses so downstream\\nanalytics and AI products can use the data safely.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Document permitted uses so downstream analytics and AI products can use the data safely.\",\n      \"quote_or_span\": \"Document data definitions, provenance, and permitted uses so downstream\\nanalytics and AI products can use the data safely.\",\n      \"importance\": \"responsibility\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Three or more years of software product-management experience.\",\n      \"quote_or_span\": \"Three or more years of software product-management experience.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Experience managing a data platform or technical data product through the full development lifecycle.\",\n      \"quote_or_span\": \"Experience managing a data platform or technical data product through the\\nfull development lifecycle.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Strong SQL skills.\",\n      \"quote_or_span\": \"Strong SQL skills and hands-on familiarity with ETL or ELT pipelines, APIs,\\ndata mapping, schema design, and data validation.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Hands-on familiarity with ETL or ELT pipelines.\",\n      \"quote_or_span\": \"Strong SQL skills and hands-on familiarity with ETL or ELT pipelines, APIs,\\ndata mapping, schema design, and data validation.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Hands-on familiarity with APIs.\",\n      \"quote_or_span\": \"Strong SQL skills and hands-on familiarity with ETL or ELT pipelines, APIs,\\ndata mapping, schema design, and data validation.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Hands-on familiarity with data mapping.\",\n      \"quote_or_span\": \"Strong SQL skills and hands-on familiarity with ETL or ELT pipelines, APIs,\\ndata mapping, schema design, and data validation.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Hands-on familiarity with schema design.\",\n      \"quote_or_span\": \"Strong SQL skills and hands-on familiarity with ETL or ELT pipelines, APIs,\\ndata mapping, schema design, and data validation.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Hands-on familiarity with data validation.\",\n      \"quote_or_span\": \"Strong SQL skills and hands-on familiarity with ETL or ELT pipelines, APIs,\\ndata mapping, schema design, and data validation.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Demonstrated backlog management in an Agile environment.\",\n      \"quote_or_span\": \"Demonstrated backlog management, requirements writing, customer discovery,\\nand cross-functional delivery in an Agile environment.\",\n      \"importance\": \"must_have\",\n      \"dimension\": \"hard\",\n      \"parent_group\": \"requirements\"\n    },\n    {\n      \"text\": \"Demonstrated requirements writing in an Agile environment.\",\n      \"quote_or_span\": \"Demonstrated backlog management, requirements writing, customer discovery,\\nand cross-